"""Authenticate exact package-local qualification evidence; no live authority."""
from pathlib import Path
import hashlib,json
V4=Path(__file__).resolve().parents[2]
ARCHIVE=V4/'runtime/finite_qualification'

def _digest(path):
    h=hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda:stream.read(1048576),b''):h.update(block)
    return h.hexdigest()

def _index():
    value=json.loads((ARCHIVE/'INDEX.json').read_text())
    if value.get('schema')!='FiniteQualificationArchive/1':raise ValueError('QualificationArchiveRequired')
    return value

def _local(origin):
    key=str(origin).replace('\\','/').casefold()
    index=_index()
    matches=[row for name,row in index['records'].items() if name.replace('\\','/').casefold()==key]
    if len(matches)!=1:raise ValueError('UnboundQualificationOrigin',str(origin))
    row=matches[0];path=(V4/row['local']).resolve()
    if not path.is_relative_to(ARCHIVE) or _digest(path)!=row['sha256']:
        raise ValueError('ChangedLocalQualification',str(origin))
    return path

def _read(origin):return json.loads(_local(origin).read_text())
def _sha(origin):return _digest(_local(origin))

